<?php $this->assign('title', 'Suscripción #' . (int)$subscription->id); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><a class="small" href="/admin/subscriptions">← Suscripciones</a><h1 class="h2 mb-1">Suscripción #<?= (int)$subscription->id ?></h1><p class="text-muted mb-0"><?= h($subscription->user->email ?? '') ?></p></div><span class="badge text-bg-secondary align-self-center"><?= h($subscription->status) ?></span></div>
<div class="row g-4"><div class="col-lg-8"><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Periodo y plan</h2><dl class="row mb-0"><dt class="col-sm-4">Plan</dt><dd class="col-sm-8"><?= h($subscription->plan_slug) ?></dd><dt class="col-sm-4">Inicio</dt><dd class="col-sm-8"><?= h($subscription->starts_at) ?></dd><dt class="col-sm-4">Vencimiento</dt><dd class="col-sm-8"><?= h($subscription->ends_at ?: '—') ?></dd><dt class="col-sm-4">Gracia hasta</dt><dd class="col-sm-8"><?= h($subscription->grace_ends_at ?: '—') ?></dd><dt class="col-sm-4">Notas</dt><dd class="col-sm-8"><?= h($subscription->notes ?: '—') ?></dd></dl></div></section><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Pagos</h2><div class="table-wrap"><table class="table table-sm"><thead><tr><th>Referencia</th><th>Estado</th><th>Monto</th><th></th></tr></thead><tbody><?php foreach ($subscription->payments as $payment): ?><tr><td><?= h($payment->internal_reference) ?></td><td><?= h($payment->status) ?></td><td>$<?= number_format((int)$payment->amount, 0, ',', '.') ?></td><td><a href="/admin/payments/<?= (int)$payment->id ?>">Ver</a></td></tr><?php endforeach; ?></tbody></table></div></div></section><section class="card admin-card"><div class="card-body"><h2 class="h5">Eventos</h2><?php foreach ($audits as $audit): ?><div class="border-bottom py-2"><strong class="small"><?= h($audit->action) ?></strong><small class="d-block text-muted"><?= h($audit->created) ?></small></div><?php endforeach; ?></div></section></div>
<aside class="col-lg-4"><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Extender y activar</h2><?= $this->Form->create(null, ['url' => '/admin/subscriptions/' . $subscription->id . '/extend', 'data-admin-confirm' => '¿Extender y activar esta licencia?']) ?><label class="form-label">Días</label><input class="form-control mb-2" type="number" name="days" min="1" max="365" value="30" required><textarea class="form-control mb-2" name="reason" required maxlength="500" placeholder="Motivo administrativo"></textarea><button class="btn btn-primary w-100">Extender licencia</button><?= $this->Form->end() ?></div></section><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Estado</h2><?= $this->Form->create(null, ['url' => '/admin/subscriptions/' . $subscription->id . '/process-expiration', 'class' => 'mb-2', 'data-admin-confirm' => '¿Procesar el vencimiento de esta licencia?']) ?><input class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo"><button class="btn btn-outline-secondary w-100">Procesar vencimiento</button><?= $this->Form->end() ?><?php if ($subscription->status !== 'suspended'): ?><?= $this->Form->create(null, ['url' => '/admin/subscriptions/' . $subscription->id . '/suspend', 'class' => 'mb-2', 'data-admin-confirm' => '¿Suspender esta licencia?']) ?><input class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo"><button class="btn btn-warning w-100">Suspender</button><?= $this->Form->end() ?><?php endif; ?><?= $this->Form->create(null, ['url' => '/admin/subscriptions/' . $subscription->id . '/reactivate', 'class' => 'mb-2', 'data-admin-confirm' => '¿Reactivar esta licencia?']) ?><input class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo"><button class="btn btn-success w-100">Reactivar</button><?= $this->Form->end() ?><?= $this->Form->create(null, ['url' => '/admin/subscriptions/' . $subscription->id . '/cancel', 'data-admin-confirm' => '¿Cancelar esta licencia? Esta acción requiere revisión posterior para revertirse.']) ?><input class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo"><button class="btn btn-outline-danger w-100">Cancelar</button><?= $this->Form->end() ?></div></section><section class="card admin-card"><div class="card-body"><h2 class="h5">Cambiar plan</h2><?= $this->Form->create(null, ['url' => '/admin/subscriptions/' . $subscription->id . '/plan', 'data-admin-confirm' => '¿Guardar el cambio de plan de esta licencia?']) ?><select class="form-select mb-2" name="plan_slug"><?php foreach ($plans as $slug => $name): ?><option value="<?= h($slug) ?>" <?= $subscription->plan_slug === $slug ? 'selected' : '' ?>><?= h($name) ?></option><?php endforeach; ?></select><textarea class="form-control mb-2" name="reason" required maxlength="500" placeholder="Motivo administrativo"></textarea><button class="btn btn-outline-primary w-100">Guardar plan</button><?= $this->Form->end() ?></div></section></aside></div>
